# tandem_file_generator.py

def pad_line(content, length=538):
    """Rellena la línea con espacios hasta alcanzar 'length' bytes"""
    if len(content) > length:
        raise ValueError(f"Línea demasiado larga: {len(content)} > {length}")
    return content.ljust(length)

